<script setup lang="ts">
import {computed} from 'vue';
import ModelImport from './ModelImport.vue';
import {referencedAssets} from '../storage/archive';
import {useEditor} from '../stores/editor';
import {createFurniture,furnitureNames} from '../domain/furniture';
import {bounds} from '../domain/geometry';
import type {AssetRecord,FurnitureKind} from '../domain/types';
const e=useEditor();
const models=computed(()=>{const ids=referencedAssets(e.document);return e.assets.filter(a=>a.kind==='model'&&ids.has(a.id));});
function add(kind:FurnitureKind,asset?:AssetRecord){const item=createFurniture(kind);if(asset){item.assetId=asset.id;item.name=asset.name;const b=asset.stats?.bounds??[1,1,1];item.width=Math.max(.02,b[0]);item.height=Math.max(.02,b[1]);item.depth=Math.max(.02,b[2]);}const room=e.document.rooms.find(r=>r.id===e.selected?.id)||e.document.rooms[0];if(room){const b=bounds(room.points);item.x=(b.minX+b.maxX)/2;item.z=(b.minZ+b.maxZ)/2;}if(e.edit('Добавить мебель',p=>{p.variants.find(v=>v.id===p.activeVariantId)!.furniture.push(item);}))e.selected={kind:'furniture',id:item.id};}
</script>
<template><section><h2>Каталог мебели</h2><p class="hint">Добавьте предмет и подгоните размеры под свою мебель. На плане предметы можно двигать мышью.</p><div class="catalog-grid"><button v-for="kind in (['wardrobe','shelf','cabinet','table','sofa','bed'] as const)" :aria-label="'Добавить '+furnitureNames[kind].toLowerCase()" @click="add(kind)"><span class="catalog-symbol">{{({wardrobe:'▥',shelf:'▤',cabinet:'▣',table:'⊓',sofa:'▰',bed:'▱'})[kind]}}</span>{{furnitureNames[kind]}}</button></div><h3>Свои модели</h3><ModelImport/><button v-for="asset in models" class="room-item" :aria-label="'Разместить '+asset.name" @click="add('asset',asset)">{{asset.name}}</button><h3>Расстановки</h3><label>Вариант расстановки<select :value="e.document.activeVariantId" @change="e.edit('Выбрать вариант',p=>{p.activeVariantId=($event.target as HTMLSelectElement).value})"><option v-for="v in e.document.variants" :value="v.id">{{v.name}}</option></select></label><button class="wide" @click="e.copyVariant">Копия варианта</button><label>Название варианта<input :value="e.variant.name" @change="e.edit('Название варианта',p=>{p.variants.find(v=>v.id===p.activeVariantId)!.name=($event.target as HTMLInputElement).value})"></label><h3>В этой расстановке · {{e.variant.furniture.length}}</h3><button v-for="f in e.variant.furniture" :class="['room-item',{active:e.selected?.id===f.id}]" @click="e.selected={kind:'furniture',id:f.id}">{{f.name}}</button><p v-if="!e.variant.furniture.length" class="hint">Предметов пока нет.</p></section></template>
